// Fail-closed auth. This endpoint drives an autonomous agent that can spend Sendr quota and
// publish public pages — an open endpoint here is strictly worse than on the single-purpose
// workflows, because the caller supplies free-text INSTRUCTIONS rather than a fixed payload.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');

const body = item.body || {};
const instruction = String(body.instruction || '').trim();
if (!instruction) throw new Error('REFUSED: no instruction supplied');
// Treat the instruction as DATA the agent reasons about, never as configuration. Anything that
// spends money or reaches a prospect is gated by tool wiring, not by what this string says.
return { json: { instruction, requested_by: body.requested_by || 'unknown' } };

// Mirrors reach-engine/engine.py's validate_config() exactly. The config is the contract:
// nothing downstream may run against one that fails this.
const CONFIGS = {
  oryoniq: {
    product: 'OryonIQ',
    one_liner: 'AI market intelligence for GovCon — who is winning the work, who they team with, and who you already know inside the agency.',
    signal: 'The Pentagon suspended CMMC Phase II on July 13, 2026 — third-party assessments are paused pending a 60-day review, while DoD committed $32B to AI, cloud, and cyber in H1 FY2026. The bid barrier just dropped on a lot of money.',
    offer: "OryonIQ shows you who has been winning the work you bid on, who they teamed with to win it, and whether anyone you already know sits inside the agency deciding it. Award data and relationship data on one map.",
    cta: 'https://meetings.hubspot.com/gavriel-legynd17/oryoniq-sales?uuid=6326f9ce-c95c-4c5c-b078-80d77911fe1f',
    postal_address: 'OryonIQ, 1 Woodward Ave, Suite 1900, Detroit, MI 48226',
    opt_out_line: 'Not interested? Reply "unsubscribe" and I will take you off the list.',
    sender: 'Ellen\nOryonIQ',
    personalization_prompt: 'Write ONE specific opening line (max 2 sentences) for a cold email to {first_name}, {title} at {company} — a US government contractor. Tie the current signal to their capture/BD reality. Do NOT invent specific facts about {company}; keep it about their role and the signal.',
    icp: { person_titles: ['Capture Manager', 'VP of Business Development'], person_locations: ['United States'] },
  },
  visioneerit: {
    product: 'VisioneerIT',
    one_liner: 'AI automation, cybersecurity, and digital modernization for federal & SLED agencies.',
    signal: "Every DoD component has to reach zero-trust architecture by September 30, 2027, and that deadline hasn't moved — while AI procurement mandates land on top of it. Security and modernization budgets are committed now.",
    offer: 'VisioneerIT stands up zero-trust architecture and AI-assisted security operations for federal and SLED teams, and gets it running in months rather than as a multi-year program, with CMMC readiness handled alongside.',
    cta: 'https://www.visioneerit.com/contact',
    postal_address: 'VisioneerIT, 1 Woodward Ave, Suite 1900, Detroit, MI 48226',
    opt_out_line: 'Not interested? Reply "unsubscribe" and I will take you off the list.',
    sender: 'Ellen, VisioneerIT',
    personalization_prompt: 'Write ONE specific opening line (max 2 sentences) for a cold email to {first_name}, {title} at {company} — a federal or SLED organization. Tie the current signal to their security/modernization mandate. Do NOT invent specific facts about {company}.',
    icp: { person_titles: ['CIO', 'CISO', 'Director of IT'], person_locations: ['United States'] },
  },
};

const key = String(query || '').toLowerCase().replace(/[^a-z]/g, '');
const cfg = CONFIGS[key];
if (!cfg) {
  return JSON.stringify({ valid: false, errors: [`unknown product "${query}" — only OryonIQ and VisioneerIT exist`] });
}

const REQUIRED = ['product', 'one_liner', 'signal', 'offer', 'cta', 'sender', 'personalization_prompt', 'postal_address', 'opt_out_line'];
const errors = [];
for (const k of REQUIRED) {
  const v = cfg[k];
  if (typeof v !== 'string' || !v.trim()) errors.push(`'${k}' must be a non-empty string`);
  else if (v.includes('<') && v.includes('>')) errors.push(`'${k}' still has a template placeholder`);
}
if (!Array.isArray(cfg.icp?.person_titles) || !cfg.icp.person_titles.length) errors.push("'icp.person_titles' must be a non-empty list");
if (!Array.isArray(cfg.icp?.person_locations) || !cfg.icp.person_locations.length) errors.push("'icp.person_locations' must be a non-empty list");
for (const token of ['{first_name}', '{company}']) {
  if (!cfg.personalization_prompt.includes(token)) errors.push(`'personalization_prompt' must contain ${token}`);
}

return JSON.stringify({
  valid: errors.length === 0,
  errors,
  product: cfg.product,
  one_liner: cfg.one_liner,
  signal: cfg.signal,
  offer: cfg.offer,
  cta: cfg.cta,
  postal_address: cfg.postal_address,
  opt_out_line: cfg.opt_out_line,
});

// The agent now returns a PLAN OBJECT (see the `Structured Plan` output parser), not free text.
// The schema makes a plan well-FORMED; this node makes it well-BEHAVED, and it runs before any
// caller acts on the response. Two classes of failure a schema cannot catch on its own:
//   1. Self-inconsistency — naming gated steps while claiming blocked:false, or claiming
//      config_valid:true for product "none". Each field is individually legal; together they lie.
//   2. Over budget — the schema's maxima are a structural ceiling that catches obvious garbage.
//      The numbers below are the operating budget a human actually set, which is tighter.
// A rejected plan comes back ok:false with its reasons. Nothing here executes anything: this
// workflow holds no gated tool at all. The point is that an over-budget or incoherent plan is
// visibly refused rather than quietly passed downstream to whoever called the webhook.
//
// Strings are control-character-scrubbed on the way out. n8n's lastNode response serialises them
// with RAW newlines, so an un-scrubbed multi-line string produces JSON that strict parsers reject
// (`Invalid control character at ...`). Found live 2026-08-16 — every consumer hit it, not one.

const BUDGET = { leads: 25, apollo_credits: 25, reoon_credits: 25, openai_calls: 60 };

const scrub = (s) => String(s).replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim();
const deepScrub = (v) =>
  Array.isArray(v) ? v.map(deepScrub)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, deepScrub(x)]))
  : (typeof v === 'string' ? scrub(v) : v);

const out = $input.first().json;
const parsed = out && out.output;

const rejected = [];
let plan = null;

if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
  plan = deepScrub(parsed);
} else {
  // No parsed object means the output parser did not run, or did not produce one. Refuse rather
  // than fall back to free text — an unvalidated plan is precisely what the parser was added to
  // stop, so silently accepting one would undo the change.
  rejected.push('agent did not return a structured plan object');
}

if (plan) {
  // A gated_steps value that is not an array must REJECT, not degrade to []. Coercing an
  // unrecognised shape to "no gated steps" makes a plan naming gated work look free, which is
  // the exact inversion this node exists to prevent. The output parser's schema makes this
  // unreachable today; this node is the layer that must not depend on that staying true.
  if (plan.gated_steps !== undefined && !Array.isArray(plan.gated_steps)) {
    rejected.push(`gated_steps must be an array, got ${typeof plan.gated_steps} — refusing rather than treating it as none`);
  }
  const gated = Array.isArray(plan.gated_steps) ? plan.gated_steps : [];
  const cost = (plan.estimated_credit_cost && typeof plan.estimated_credit_cost === 'object' && !Array.isArray(plan.estimated_credit_cost))
    ? plan.estimated_credit_cost : {};
  const num = (v) => (typeof v === 'number' && Number.isFinite(v)) ? v : NaN;

  if (gated.length > 0 && plan.blocked !== true) {
    rejected.push(`plan names gated steps (${gated.join(', ')}) but sets blocked:false — a gated step is never unblocked here`);
  }
  if (plan.config_valid !== true && plan.blocked !== true
      && plan.intended_action !== 'refuse' && plan.intended_action !== 'report_only') {
    rejected.push('plan proceeds unblocked on a config it did not validate');
  }
  if (plan.product === 'none' && plan.config_valid === true) {
    rejected.push("config_valid:true with product 'none' — nothing was validated");
  }

  const leads = num(plan.lead_count);
  if (!Number.isFinite(leads)) rejected.push('lead_count is not a number');
  else if (leads > BUDGET.leads) rejected.push(`lead_count ${leads} exceeds the budget of ${BUDGET.leads}`);

  for (const k of ['apollo_credits', 'reoon_credits', 'openai_calls']) {
    const v = num(cost[k]);
    if (!Number.isFinite(v)) rejected.push(`estimated_credit_cost.${k} is not a number`);
    else if (v > BUDGET[k]) rejected.push(`estimated_credit_cost.${k} ${v} exceeds the budget of ${BUDGET[k]}`);
  }

  // Apollo spends one credit per revealed contact, so a plan cannot cost more reveals than it has
  // leads. A plan claiming otherwise was not costed, it was guessed — and a guessed cost is the
  // one number a human approving a spend is relying on.
  const ap = num(cost.apollo_credits);
  if (Number.isFinite(ap) && Number.isFinite(leads) && ap > leads) {
    rejected.push(`estimated_credit_cost.apollo_credits ${ap} exceeds lead_count ${leads}`);
  }
}

const ok = rejected.length === 0;

return [{ json: {
  ok,
  plan,
  rejected,
  report: plan ? scrub(plan.report || '') : '',
  tools_available: ['validate_config', 'log_to_sheet'],
  gated_actions_available: [],
  note: ok
    ? 'Plan is well-formed and within budget. That is NOT approval to run it. This agent holds two free, reversible tools — validate_config and log_to_sheet. Revealing contacts, enrolling into Instantly, sending email and placing calls have no tool here at all: they are absent, not merely discouraged by the prompt.'
    : 'Plan REJECTED before anything acted on it — see `rejected`. This agent holds only free, reversible tools, so there was nothing gated for it to have run in the meantime either.',
} }];

parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "intended_action",
    "product",
    "config_valid",
    "lead_count",
    "estimated_credit_cost",
    "gated_steps",
    "blocked",
    "report"
  ],
  "properties": {
    "intended_action": {
      "type": "string",
      "enum": [
        "validate_config",
        "draft_opener",
        "propose_plan",
        "refuse",
        "report_only"
      ],
      "description": "The single thing this turn does or proposes. 'refuse' when you are turning down a request; 'report_only' when the turn touches no product and no leads."
    },
    "product": {
      "type": "string",
      "enum": [
        "OryonIQ",
        "VisioneerIT",
        "none"
      ],
      "description": "Which product config this turn is about. Only these two products exist — never invent a third. Use 'none' when the turn is not product-specific."
    },
    "config_valid": {
      "type": "boolean",
      "description": "True ONLY if you called validate_config this turn and it returned valid:true. If you did not call it, this is false. Never assert it from memory."
    },
    "lead_count": {
      "type": "integer",
      "minimum": 0,
      "maximum": 50,
      "description": "How many leads this plan touches. 0 when it touches none."
    },
    "estimated_credit_cost": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "apollo_credits",
        "reoon_credits",
        "openai_calls"
      ],
      "description": "What the plan would cost if a human approved it. All zero for a plan that spends nothing.",
      "properties": {
        "apollo_credits": {
          "type": "integer",
          "minimum": 0,
          "maximum": 50,
          "description": "One credit per revealed contact. Can never exceed lead_count."
        },
        "reoon_credits": {
          "type": "integer",
          "minimum": 0,
          "maximum": 50,
          "description": "One credit per email verified."
        },
        "openai_calls": {
          "type": "integer",
          "minimum": 0,
          "maximum": 200,
          "description": "Model calls the plan would make, e.g. one opener per lead."
        }
      }
    },
    "gated_steps": {
      "type": "array",
      "description": "EVERY step in this plan that spends money or reaches a prospect, even one you are only proposing. An empty array means the plan is entirely free and reversible.",
      "items": {
        "type": "string",
        "enum": [
          "reveal_contacts",
          "verify_emails",
          "push_to_instantly",
          "send_email",
          "generate_page",
          "other"
        ]
      }
    },
    "blocked": {
      "type": "boolean",
      "description": "True whenever gated_steps is non-empty, or config_valid is false. When true you have NOT executed the plan and must not."
    },
    "report": {
      "type": "string",
      "description": "Plain English for the human: what you did, what came back, and what a human must do next."
    }
  }
}
